const e = $input.first().json;
const miss = ['envelope_version','business_id','lead_id','trace_id'].filter(k => !e[k]);
if (miss.length) throw new Error('LEAD:' + (e.lead_id || '') + '|TRACE:' + (e.trace_id || '') + '|invalid envelope, missing: ' + miss.join(', '));
if (e.envelope_version !== '1.0') throw new Error('LEAD:' + e.lead_id + '|TRACE:' + e.trace_id + '|unsupported envelope_version ' + e.envelope_version);
return [{ json: e }];

const raw = $input.first().json;
let r = raw;
if (r && Array.isArray(r.candidates)) r = { content: (r.candidates[0] || {}).content };
if (r && r.content && Array.isArray(r.content.parts)) r = r.content.parts.map(p => p.text || "").join("");
else if (r.content !== undefined) r = r.content;
else if (r.text !== undefined) r = r.text;
if (typeof r === "string") { try { r = JSON.parse(r.replace(/^```json?s*|```s*$/g, "")); } catch (e) { r = null; } }
const errs = [];
if (!r || typeof r !== 'object') errs.push('not an object');
else {
  if (!['ENQUIRY','NOT_ENQUIRY','SPAM'].includes(r.classification)) errs.push('bad classification');
  if (typeof r.confidence !== 'number' || r.confidence < 0 || r.confidence > 1) errs.push('bad confidence');
  if (!Array.isArray(r.product_interest)) errs.push('product_interest not array');
  if (r.budget_value !== null && r.budget_value !== undefined && typeof r.budget_value !== 'number') errs.push('bad budget_value');
  if (r.urgency != null && !['high','medium','low'].includes(r.urgency)) errs.push('bad urgency');
}
const lead = $('Fetch Lead').first().json;
return [{ json: { valid: errs.length === 0, errors: errs, attempt: 1,
  parsed: r || {}, lead_id: lead.lead_id, business_id: lead.business_id, trace_id: lead.trace_id } }];

